1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class,
19	    imports = {LocalityDeriver.class, IdentityKeyDeriver.class, CheckDigitDeriver.class,
20	        AgeBandDeriver.class, TelephoneDisplayDeriver.class, MembershipPointsDeriver.class,
21	        FiscalYearDeriver.class, OwnerSegmentDeriver.class})
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "selfLink",
25	        expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "salutation",
29	        expression = "java((owner.getTitle() != null && !owner.getTitle().isBlank()) "
30	            + "? owner.getTitle() + \" \" + owner.getLastName() : owner.getLastName())")
31	    @Mapping(target = "initials",
32	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
33	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
34	    @Mapping(target = "checkDigit",
35	        expression = "java(CheckDigitDeriver.checkDigit(owner.getCustomerCode()))")
36	    @Mapping(target = "membershipNumber",
37	        expression = "java(owner.getCustomerCode() + \"-M\" "
38	            + "+ String.format(\"%02d\", FiscalYearDeriver.fiscalYear("
39	            + "owner.getRegistrationDate()) % 100))")
40	    @Mapping(target = "fiscalYear",
41	        expression = "java(FiscalYearDeriver.fiscalYearLabel(owner.getRegistrationDate()))")
42	    @Mapping(target = "membershipPoints",
43	        expression = "java(MembershipPointsDeriver.membershipPoints(owner))")
44	    @Mapping(target = "membershipLevel",
45	        expression = "java(MembershipPointsDeriver.effectiveMembershipLevel(owner))")
46	    @Mapping(target = "locality",
47	        expression = "java(LocalityDeriver.locality(owner.getCustomerCode()))")
48	    @Mapping(target = "timezone",
49	        expression = "java(LocalityDeriver.timezone("
50	            + "LocalityDeriver.locality(owner.getCustomerCode())))")
51	    @Mapping(target = "ownerSegment",
52	        expression = "java(OwnerSegmentDeriver.ownerSegment("
53	            + "MembershipPointsDeriver.effectiveMembershipLevel(owner), "
54	            + "LocalityDeriver.locality(owner.getCustomerCode())))")
55	    @Mapping(target = "contactPreference",
56	        expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) "
57	            + "? \"EMAIL\" : \"PHONE\")")
58	    @Mapping(target = "ageBand",
59	        expression = "java(AgeBandDeriver.ageBand(owner.getBirthDate(), "
60	            + "owner.getRegistrationDate()))")
61	    @Mapping(target = "identityKey",
62	        expression = "java(IdentityKeyDeriver.identityKey(owner.getTelephone(), "
63	            + "owner.getEmail(), owner.getLastName()))")
64	    @Mapping(target = "telephoneDisplay",
65	        expression = "java(TelephoneDisplayDeriver.telephoneDisplay(owner.getTelephone()))")
66	    OwnerDto toOwnerDto(Owner owner);
67	
68	    Owner toOwner(OwnerDto ownerDto);
69	
70	    @Mapping(target = "id", ignore = true)
71	    @Mapping(target = "pets", ignore = true)
72	    Owner toOwner(OwnerFieldsDto ownerDto);
73	
74	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
75	
76	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
77	
78	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
79	        OwnerPageDto ownerPageDto = new OwnerPageDto();
80	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
81	        ownerPageDto.setPage(ownerPage.getNumber());
82	        ownerPageDto.setSize(ownerPage.getSize());
83	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
84	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
85	        return ownerPageDto;
86	    }
87	}
