212	                : LocalDate.now());
213	        long registeredOnDay = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
215	            .count();
216	        if (registeredOnDay >= 100) {
217	            throw new DailyRegistrationLimitException(
218	                "100 or more owners have already been registered today");
219	        }
220	        boolean bulkSignupWarning = registeredOnDay > 80;
221	        String city = ownerFieldsDto.getCity();
222	        long ownersInCity = this.clinicService.findAllOwners().stream()
223	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
224	            .count();
225	        if (ownersInCity >= 50) {
226	            throw new CityAtCapacityException(
227	                "the owner's city already contains 50 or more owners");
228	        }
229	        // Soft warning as the city approaches its hard capacity of 50: flag owners created while
230	        // their city already holds between 40 and 49 owners. Computed on create and returned
231	        // unchanged thereafter.
232	        boolean capacityWarning = ownersInCity >= 40;
233	        String telephone = toE164(ownerFieldsDto.getTelephone());
234	        ownerFieldsDto.setTelephone(telephone);
235	        String email = normalizeEmail(ownerFieldsDto.getEmail());
236	        ownerFieldsDto.setEmail(email);
237	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
238	        String postcode = ownerFieldsDto.getPostcode();
239	        // Deterministic household id: owners with the same normalized last name and postcode
240	        // share it automatically, regardless of creation order. It is no longer created by the
241	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
242	        String householdId = householdId(lastName, postcode);
243	        // The household is keyed on (last name, postcode), so its existing members are the
244	        // existing owners with the same computed household id. Both the duplicate block and the
245	        // household size below key off this value.
246	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
247	            .filter(existing -> !existing.isDeleted())
248	            .filter(existing -> householdId.equals(
249	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
250	            .toList();
251	        // A second owner in an existing household is admitted as a household member; their
252	        // membership level is capped below (level-ceiling rule) rather than rejected.
253	        // Single, consolidated duplicate check: reject only when the new owner's whole derived
254	        // identity key (SHA-256 over telephone|email|soundex(lastName)) equals an existing,
255	        // non-deleted owner's. This single identity key is the only 409; there is no separate
256	        // household-duplicate rejection keyed off the computed householdId.
257	        String newLastName = ownerFieldsDto.getLastName();
258	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, newLastName);
259	        boolean identityInUse = this.clinicService.findAllOwners().stream()
260	            .filter(existing -> !existing.isDeleted())
261	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
262	                existing.getTelephone(), existing.getEmail(), existing.getLastName())));
263	        if (identityInUse) {
264	            throw new DuplicateIdentityException(
265	                "an owner with the same identity key already exists");
266	        }
267	        // Soft match: not a hard duplicate, but shares a household signature with an existing,
268	        // non-deleted owner — the same last-name Soundex and the same postcode while the identity
269	        // key differs (e.g. same last name and postcode but a different telephone). Such an owner
270	        // is still created (201) but flagged as a possible duplicate of the earliest matching owner
271	        // so it can be reviewed rather than rejected.
272	        String newSoundex = IdentityKeyDeriver.soundex(newLastName);
273	        Integer softMatchOf = this.clinicService.findAllOwners().stream()
274	            .filter(existing -> !existing.isDeleted())
275	            .filter(existing -> !identityKey.equals(IdentityKeyDeriver.identityKey(
276	                existing.getTelephone(), existing.getEmail(), existing.getLastName())))
277	            .filter(existing -> newSoundex.equals(IdentityKeyDeriver.soundex(existing.getLastName())))
278	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
279	            .map(Owner::getId)
280	            .min(Integer::compareTo)
281	            .orElse(null);
282	        HttpHeaders headers = new HttpHeaders();
283	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
284	        owner.setRegistrationDate(registrationDate);
285	        owner.setCustomerCode(deduplicateCustomerCode(
286	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
287	        owner.setHouseholdId(householdId);
288	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
289	        owner.setBulkSignupWarning(bulkSignupWarning);
290	        owner.setCapacityWarning(capacityWarning);
291	        // Household size after this create: existing members plus the owner being created.
292	        owner.setHouseholdSize(householdMembers.size() + 1);
293	        // Level-ceiling: the new owner's membership level cannot exceed one above the current
294	        // maximum level among their existing household members. With no existing member no cap
295	        // applies. The (possibly capped) level is stored so it is returned on create and on read.
296	        int naturalLevel = MembershipPointsDeriver.membershipLevel(
297	            MembershipPointsDeriver.membershipPoints(owner));
298	        int cappedLevel = naturalLevel;
299	        if (!householdMembers.isEmpty()) {
300	            int maxMemberLevel = householdMembers.stream()
301	                .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
302	                .max()
303	                .orElseThrow();
304	            cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
305	        }
306	        owner.setMembershipLevel(cappedLevel);
307	        // Flag a soft match (same last-name Soundex and postcode as an existing owner, but a
308	        // different identity key) as a possible duplicate of the earliest such owner; a create
309	        // with no soft match is left unflagged.
310	        owner.setPossibleDuplicate(softMatchOf != null);
311	        owner.setPossibleDuplicateOf(softMatchOf);
312	        owner.setDeleted(false);
313	        this.clinicService.saveOwner(owner);
314	        if (idempotencyKey != null) {
315	            idempotentCreates.put(idempotencyKey, owner.getId());
316	        }
317	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
318	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
319	            + "membershipNumber={}",
320	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
321	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
322	        emitOwnerCreatedEvent(owner, ownerDto);
323	        headers.setLocation(UriComponentsBuilder.newInstance()
324	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
325	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
326	    }
