443	    /**
444	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
445	     * rolled forward, just as a weekend is, to the next non-holiday business day.
446	     */
447	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
448	        LocalDate.of(2026, 1, 1),
449	        LocalDate.of(2026, 1, 26),
450	        LocalDate.of(2026, 4, 25),
451	        LocalDate.of(2026, 12, 25),
452	        LocalDate.of(2026, 12, 28));
453	
454	    /**
455	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
456	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
457	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
458	     * registration date (whether supplied in the request or defaulted to the server date), so every
459	     * value derived from the registration date sees the adjusted business day.
460	     */
461	    private static LocalDate toBusinessDay(LocalDate date) {
462	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
463	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
464	                || PUBLIC_HOLIDAYS.contains(date)) {
465	            date = date.plusDays(1);
466	        }
467	        return date;
468	    }
