470	    /**
471	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
472	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
473	     * lower-cased so that last names are compared case-insensitively.
474	     */
475	    private static String normalizeHousehold(String value) {
476	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
477	    }
478	
479	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
480	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
481	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
482	
483	    /**
484	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
485	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
486	     * upper-cased, and common street-type abbreviations are expanded token-by-token
487	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
488	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
489	     * used for every address comparison (household-duplicate detection and the shared household id).
490	     */
491	    private static String normalizeAddress(String value) {
492	        if (value == null) {
493	            return "";
494	        }
495	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
496	        if (collapsed.isEmpty()) {
497	            return "";
498	        }
499	        String[] tokens = collapsed.split(" ");
500	        StringBuilder sb = new StringBuilder();
501	        for (int i = 0; i < tokens.length; i++) {
502	            if (i > 0) {
503	                sb.append(' ');
504	            }
505	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
506	        }
507	        return sb.toString();
508	    }
509	
510	    /**
511	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
512	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
513	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
514	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
515	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
516	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
517	     * The resulting {@code address} is the effective value every address reader sees, and is blank
518	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
519	     */
520	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
521	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
522	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
523	        if (!isBlank(line1)) {
524	            ownerFieldsDto.setAddressLine1(line1);
525	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
526	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
527	        } else {
528	            ownerFieldsDto.setAddressLine1(null);
529	            ownerFieldsDto.setAddressLine2(null);
530	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
531	        }
532	    }
