534	    /**
535	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
536	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
537	     * deterministic function of the normalized last name and postcode, so every owner that shares
538	     * those values maps to the same identifier regardless of creation order. A {@code null}
539	     * postcode contributes the empty string.
540	     */
541	    private static String householdId(String normalizedLastName, String postcode) {
542	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
543	        return sha256Hex12(key);
544	    }
545	
546	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
547	    private static String sha256Hex12(String s) {
548	        try {
549	            byte[] digest = MessageDigest.getInstance("SHA-256")
550	                .digest(s.getBytes(StandardCharsets.UTF_8));
551	            StringBuilder sb = new StringBuilder(12);
552	            for (int i = 0; i < 6; i++) {
553	                sb.append(String.format("%02x", digest[i]));
554	            }
555	            return sb.toString();
556	        }
557	        catch (NoSuchAlgorithmException e) {
558	            throw new IllegalStateException("SHA-256 not available", e);
559	        }
560	    }
