562	    /**
563	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger as a
564	     * compact JSON object {@code {seq, ownerId, customerCode, membershipLevel, event}}. {@code seq}
565	     * is a process-wide monotonically increasing sequence across creates. The event carries the
566	     * owner's current primary identifier via {@link #primaryIdentifier(Owner)} — the customerCode
567	     * today, and whatever supersedes it later — so consumers always see the identifier in force.
568	     */
569	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
570	        Map<String, Object> event = new LinkedHashMap<>();
571	        event.put("seq", CREATE_EVENT_SEQ.incrementAndGet());
572	        event.put("ownerId", owner.getId());
573	        event.put("customerCode", primaryIdentifier(owner));
574	        event.put("membershipLevel", ownerDto.getMembershipLevel());
575	        event.put("event", OWNER_CREATED_EVENT);
576	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
577	    }
