579	    /**
580	     * The owner's current primary identifier carried by structured audit events. This is the single
581	     * point that changes when the {@code customerCode} is unified into the {@code memberId}: today it
582	     * returns the {@code customerCode}, and returning the {@code memberId} here later makes every
583	     * event carry the {@code memberId} instead, with no other change required.
584	     */
585	    private static String primaryIdentifier(Owner owner) {
586	        return owner.getCustomerCode();
587	    }
588	
589	    /**
590	     * Builds the {@code customerCode} assigned to a new owner, formatted
591	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
592	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
593	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
594	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
595	     * pure function of the owner's own identity fields.
596	     */
597	    private static String customerCode(String postcode, String telephone, String lastName) {
598	        String region = LocalityDeriver.region(postcode);
599	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
600	            + (lastName == null ? "" : lastName));
601	        return region + "-" + hash8;
602	    }
603	
604	    /**
605	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
606	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
607	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
608	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
609	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
610	     */
611	    private String deduplicateCustomerCode(String base) {
612	        Set<String> existing = this.clinicService.findAllOwners().stream()
613	            .map(Owner::getCustomerCode)
614	            .filter(code -> code != null)
615	            .collect(Collectors.toSet());
616	        if (!existing.contains(base)) {
617	            return base;
618	        }
619	        int n = 2;
620	        while (existing.contains(base + "-" + n)) {
621	            n++;
622	        }
623	        return base + "-" + n;
624	    }
625	
626	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
627	    private static String sha256Hex8(String s) {
628	        try {
629	            byte[] digest = MessageDigest.getInstance("SHA-256")
630	                .digest(s.getBytes(StandardCharsets.UTF_8));
631	            StringBuilder sb = new StringBuilder(8);
632	            for (int i = 0; i < 4; i++) {
633	                sb.append(String.format("%02X", digest[i]));
634	            }
635	            return sb.toString();
636	        }
637	        catch (NoSuchAlgorithmException e) {
638	            throw new IllegalStateException("SHA-256 not available", e);
639	        }
640	    }
641	
642	    /**
643	     * Counts the existing owners that share the given first name and last name, compared
644	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
645	     * owner currently being created is saved), so it reflects how many namesakes preceded the
646	     * new owner.
647	     */
648	    private int countNamesakes(String firstName, String lastName) {
649	        return (int) this.clinicService.findAllOwners().stream()
650	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
651	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
652	            .count();
653	    }
