655	    /**
656	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
657	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
658	     * national one, a single leading {@code '0'} is dropped, and the default country code
659	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
660	     * national number must have the length required by its country code ({@code '+61'} requires 9
661	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
662	     * raised (reported to the client as 400).
663	     */
664	    private static String toE164(String telephone) {
665	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
666	        String digits;
667	        if (cleaned.startsWith("+")) {
668	            digits = cleaned.substring(1);
669	        } else {
670	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
671	            digits = "61" + national;
672	        }
673	        if (!digits.matches("[0-9]{8,15}")) {
674	            throw new InvalidTelephoneException(
675	                "telephone must form a valid E.164 number with 8 to 15 digits");
676	        }
677	        validateNationalLength(digits);
678	        return "+" + digits;
679	    }
680	
681	    /** National-number length required for each supported country code (digits after the code). */
682	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
683	        "61", 9, "1", 10);
684	
685	    /**
686	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
687	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
688	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
689	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
690	     */
691	    private static void validateNationalLength(String digits) {
692	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
693	            String code = entry.getKey();
694	            if (digits.startsWith(code)) {
695	                int nationalLength = digits.length() - code.length();
696	                if (nationalLength != entry.getValue()) {
697	                    throw new InvalidTelephoneException(
698	                        "telephone national number must have " + entry.getValue()
699	                            + " digits for country code +" + code);
700	                }
701	                return;
702	            }
703	        }
704	    }
705	
706	    /**
707	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
708	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
709	     * any 4-digit postcode.
710	     */
711	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
712	        "NSW", new int[] {2000, 2099},
713	        "VIC", new int[] {3000, 3099},
714	        "QLD", new int[] {4000, 4099});
715	
716	    /**
717	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
718	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
719	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
720	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
721	     * no known region accepts any 4-digit postcode. A violation raises an
722	     * {@link InvalidPostcodeException} (reported to the client as 400).
723	     */
724	    private static void validatePostcode(String city, String postcode) {
725	        if (isBlank(postcode)) {
726	            return;
727	        }
728	        if (!postcode.matches("[0-9]{4}")) {
729	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
730	        }
731	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
732	        if (range == null) {
733	            return;
734	        }
735	        int value = Integer.parseInt(postcode);
736	        if (value < range[0] || value > range[1]) {
737	            throw new InvalidPostcodeException(
738	                "postcode is out of range for the owner's city region");
739	        }
740	    }
741	
742	    /**
743	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
744	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
745	     * check).
746	     */
747	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
748	        "mailinator.com", "tempmail.com", "guerrillamail.com");
749	
750	    /**
751	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
752	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
753	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
754	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
755	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
756	     * so it is stored and returned in canonical form.
757	     */
758	    private static String normalizeEmail(String email) {
759	        if (isBlank(email)) {
760	            return null;
761	        }
762	        String trimmed = email.trim();
763	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
764	            throw new InvalidEmailException("email must be a syntactically valid address");
765	        }
766	        String normalized = trimmed.toLowerCase(Locale.ROOT);
767	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
768	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
769	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
770	        }
771	        return normalized;
772	    }
773	}
