3	/**
4	 * Derives an owner's segment, formatted {@code '<TIER>_<AREA>'}, from the owner's
5	 * membership level and locality (region).
6	 *
7	 * <p>TIER is {@code PREMIUM} when the membership level is 3 or more, otherwise
8	 * {@code STANDARD}. AREA is {@code METRO} when the locality is a known region
9	 * (NSW, VIC or QLD), otherwise {@code REGIONAL}. The four possible values are
10	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} and
11	 * {@code STANDARD_REGIONAL}.
12	 *
13	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so
14	 * MapStruct does not mistake it for a generic {@code String -> String} mapping
15	 * method and apply it to unrelated fields; the mapper references it only through an
16	 * explicit expression.
17	 */
18	public final class OwnerSegmentDeriver {
19	
20	    private OwnerSegmentDeriver() {
21	    }
22	
23	    /**
24	     * Returns the owner's segment formatted {@code '<TIER>_<AREA>'}: TIER is
25	     * {@code PREMIUM} when {@code membershipLevel} is 3 or more, else {@code STANDARD};
26	     * AREA is {@code METRO} when {@code locality} is a known region (NSW, VIC or QLD),
27	     * else {@code REGIONAL}.
28	     */
29	    public static String ownerSegment(int membershipLevel, String locality) {
30	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
31	        String area = isKnownRegion(locality) ? "METRO" : "REGIONAL";
